The expected final value is 800000. On failure, compare_exchange_weak updates expected with the observed counter value; the loop must recompute desired from that updated value. Weak CAS may also fail spuriously, so retrying is necessary. Relaxed ordering suffices because the counter publishes no other memory; atomicity prevents lost increments, and joining waits for all workers.

```cpp
#include <atomic>
#include <cassert>
#include <iostream>
#include <thread>
#include <vector>

class AtomicCounter {
public:
    void increment() noexcept {
        unsigned expected = value_.load(std::memory_order_relaxed);
        for (;;) {
            const unsigned desired = expected + 1u;
            if (value_.compare_exchange_weak(
                    expected, desired,
                    std::memory_order_relaxed,
                    std::memory_order_relaxed)) {
                return;
            }
            // Failure refreshes expected; recompute desired next iteration.
        }
    }

    unsigned load() const noexcept {
        return value_.load(std::memory_order_relaxed);
    }

private:
    std::atomic<unsigned> value_{0u};
};

int main() {
    constexpr unsigned thread_count = 8u;
    constexpr unsigned increments_per_thread = 100000u;
    constexpr unsigned expected_final = 800000u;
    static_assert(thread_count * increments_per_thread == expected_final);

    AtomicCounter counter;
    assert(counter.load() == 0u);

    std::vector<std::thread> workers;
    workers.reserve(thread_count);
    for (unsigned i = 0; i < thread_count; ++i) {
        workers.emplace_back([&counter] {
            for (unsigned j = 0; j < increments_per_thread; ++j) {
                counter.increment();
            }
        });
    }
    for (auto& worker : workers) {
        worker.join();
    }

    const unsigned final_value = counter.load();
    assert(final_value == expected_final);
    std::cout << final_value << '\n';
    return final_value == expected_final ? 0 : 1;
}
```

Compile with: `g++ -std=c++17 -O2 -pthread counter.cpp -o counter`.

The expected final value is 800000. Relaxed ordering is sufficient because the counter publishes no other memory; atomicity prevents lost increments, and joining all eight threads lets main check the completed result. On compare_exchange_weak failure, expected is overwritten with the observed counter value, so the next attempt must recompute expected + 1; weak CAS can also fail spuriously, which the loop handles.

```cpp
#include <array>
#include <atomic>
#include <cassert>
#include <iostream>
#include <thread>

class AtomicCounter {
public:
    void increment() noexcept {
        unsigned expected = value_.load(std::memory_order_relaxed);
        while (!value_.compare_exchange_weak(
            expected,
            expected + 1u,
            std::memory_order_relaxed,
            std::memory_order_relaxed)) {
            // Failure updates expected. Recompute the desired value
            // from it on the next iteration; do not reset expected.
        }
    }

    unsigned load() const noexcept {
        return value_.load(std::memory_order_relaxed);
    }

private:
    std::atomic<unsigned> value_{0u};
};

int main() {
    constexpr unsigned thread_count = 8u;
    constexpr unsigned increments_per_thread = 100000u;
    constexpr unsigned expected_final = 800000u;
    static_assert(thread_count * increments_per_thread == expected_final);

    AtomicCounter counter;
    assert(counter.load() == 0u);

    std::array<std::thread, thread_count> threads;
    for (auto& thread : threads) {
        thread = std::thread([&counter] {
            for (unsigned i = 0; i < increments_per_thread; ++i) {
                counter.increment();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
        assert(!thread.joinable());
    }

    const unsigned result = counter.load();
    assert(result == expected_final);
    std::cout << result << '\n';
}
```

Compile and run with assertions enabled: `g++ -std=c++17 -O2 -pthread counter.cpp -o counter && ./counter`. Do not define `NDEBUG`.
